// Adjacency Matrix — Network, route: jsx
// Source: original:gaps/adjacency-matrix
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from adjacencyMatrix ----
// Seeded clustered graph, deliberately dense: 40 nodes in four groups with a high
// within-group link probability and a low between-group one. A force layout of this
// hairballs; ordered by group in a matrix, the same links read as blocks.
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const GROUPS = ['Core', 'UI', 'Data', 'Net'];
const NODES_PER_GROUP = 10;
const WITHIN_PROBABILITY = 0.6;
const BETWEEN_PROBABILITY = 0.15;

const rng = mulberry32(20260821);

const nodes = GROUPS.flatMap((group) =>
  Array.from({ length: NODES_PER_GROUP }, (_, i) => ({
    id: `${group.toLowerCase()}-${String(i + 1).padStart(2, '0')}`,
    group
  }))
);

const links: { source: string; target: string; value: number }[] = [];
for (let i = 0; i < nodes.length; i++) {
  for (let j = i + 1; j < nodes.length; j++) {
    const within = nodes[i].group === nodes[j].group;
    if (rng() < (within ? WITHIN_PROBABILITY : BETWEEN_PROBABILITY)) {
      links.push({ source: nodes[i].id, target: nodes[j].id, value: 1 + Math.floor(rng() * 3) });
    }
  }
}

const clusteredGraph: {
  nodes: { id: string; group: string }[];
  links: { source: string; target: string; value: number }[];
  groups: string[];
} = { nodes, links, groups: GROUPS };

const MARGIN = { top: 64, right: 8, bottom: 8, left: 64 };

/** Same shape as force-directed-graph: one dataset, two readings of it. */
export type Data = {
  nodes: { id: string; group: string }[];
  links: { source: string; target: string; value: number }[];
  groups: string[];
};

export default function AdjacencyMatrix({ data = clusteredGraph, width }: { data?: Data; width: number }) {
  const side = Math.max(1, width - MARGIN.left - MARGIN.right);
  const height = side + MARGIN.top + MARGIN.bottom;

  // Ordering IS the chart: rows grouped by cluster turn the same links into blocks.
  const ordered = useMemo(
    () =>
      [...data.nodes].sort(
        (a, b) =>
          data.groups.indexOf(a.group) - data.groups.indexOf(b.group) ||
          d3.ascending(a.id, b.id)
      ),
    [data]
  );

  const band = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(ordered.map((n) => n.id))
        .range([0, side])
        .paddingInner(0.1),
    [ordered, side]
  );

  const opacity = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data.links, (l) => l.value) ?? 1])
        .range([0.15, 0.95]),
    [data]
  );

  // Each undirected link paints two mirrored cells, colored by within- vs between-group.
  const cells = useMemo(() => {
    const groupOf = new Map(data.nodes.map((n) => [n.id, n.group]));
    return data.links.flatMap((link) => {
      const within = groupOf.get(link.source) === groupOf.get(link.target);
      return [
        { row: link.source, col: link.target, value: link.value, within },
        { row: link.target, col: link.source, value: link.value, within }
      ];
    });
  }, [data]);

  // Pixel positions of the boundaries between consecutive groups.
  const boundaries = useMemo(() => {
    const gap = (band.step() - band.bandwidth()) / 2;
    return ordered
      .slice(1)
      .filter((node, i) => node.group !== ordered[i].group)
      .map((node) => (band(node.id) ?? 0) - gap);
  }, [ordered, band]);

  const labelSize = Math.min(8, band.bandwidth());

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Adjacency matrix of a 40-node clustered network with rows and columns ordered by group, so within-group links form dense blocks along the diagonal"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <rect width={side} height={side} fill="none" stroke="var(--line)" />
        {cells.map((cell) => (
          <rect
            key={`${cell.row}-${cell.col}`}
            x={band(cell.col) ?? 0}
            y={band(cell.row) ?? 0}
            width={band.bandwidth()}
            height={band.bandwidth()}
            fill={cell.within ? 'var(--accent)' : 'var(--muted)'}
            fillOpacity={opacity(cell.value)}
          />
        ))}
        {boundaries.map((position) => (
          <g key={position}>
            <line x1={0} x2={side} y1={position} y2={position} stroke="var(--text)" strokeOpacity={0.45} />
            <line x1={position} x2={position} y1={0} y2={side} stroke="var(--text)" strokeOpacity={0.45} />
          </g>
        ))}
        {ordered.map((node) => {
          const center = (band(node.id) ?? 0) + band.bandwidth() / 2;
          return (
            <g key={node.id}>
              <text
                x={-4}
                y={center}
                dy="0.32em"
                textAnchor="end"
                fontSize={labelSize}
                fill="var(--muted)"
              >
                {node.id}
              </text>
              <text
                transform={`translate(${center},-4) rotate(-90)`}
                dy="0.32em"
                textAnchor="start"
                fontSize={labelSize}
                fill="var(--muted)"
              >
                {node.id}
              </text>
            </g>
          );
        })}
      </g>
    </svg>
  );
}
